//! 🧵️ Stack preparation retains original images and pays every node, row copy and cancelled allocation.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn stock()->RetainedCloneGrant{let f=fixture();let p=&f["stock"];RetainedCloneGrant{maximum_items:p["maximumItems"].as_u64().unwrap() as usize,maximum_copy_bytes:p["maximumCopyBytes"].as_u64().unwrap() as usize,maximum_capacity_bytes:p["maximumCapacityBytes"].as_u64().unwrap() as usize,maximum_release_bytes:p["maximumReleaseBytes"].as_u64().unwrap() as usize,maximum_depth:p["maximumDepth"].as_u64().unwrap() as usize}}
fn loan()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:4096}}
fn document()->RasterSnapshot{let f=fixture();let mut document=semio_s_artifact_raster_raster_model::io::text::snapshot::snapshot_wire_codec::empty_raster_snapshot();let mut layer=semio_s_artifact_raster_raster_model::create_pixel_layer("Paint",2,1);if let RasterLayerNode::Pixel{id,image_key,..}=&mut layer{*id="paint".into();*image_key=Some("source".into());}document.layers.push(layer);let image=semio_s_artifact_raster_raster_model::semio_image_from_rgba8(2,1,serde_json::from_value(f["source"]["pixels"].clone()).unwrap());document.assets.insert("source".into(),semio_s_artifact_raster_raster_model::mint_raster_image_child("source",&image)).unwrap();document}
fn close(caller:&mut OriginalJobFixtureCaller,owner:&mut RasterStackPreparation){owner.cancel();for turn in 0..100_000{if owner.terminal_is_empty(){return}caller.turn(loan(),|cx|{let demand=owner.close_demands(32768)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|owner.close_step(grant))?;Ok(())}).unwrap();assert!(turn<99_999);}panic!("stack preparation fixture close did not settle")}
#[test]
fn original_stack_preparation_yields_preserves_pixels_and_closes_every_cut(){let f=fixture();for cut in std::iter::once(None).chain(f["cancelAfterTurns"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap() as usize))){let mut caller=OriginalJobFixtureCaller::admit(OperationId(998),Generation(17),stock(),||Some(1),u64::MAX,1<<24);let document=document();let before=document.clone();let mut owner=RasterStackPreparation::new(&document).unwrap();let mut turns=0;while !owner.output_ready()&&cut.is_none_or(|cut|turns<cut){let demand=owner.demands(32768).unwrap();let denied=owner.advance(&document,32768,RetainedCloneGrant::default());assert_eq!(denied.result.unwrap().progress(),Default::default());assert_eq!(owner.demands(32768).unwrap(),demand);caller.turn(loan(),|cx|{let turn=owner.advance(&document,32768,cx.retained_grant());semio_framework_job::receive_original_retained_work(cx,turn)?;Ok(())}).unwrap();turns+=1;assert!(turns<100_000);}if cut.is_none(){let mut output=None;caller.turn(loan(),|cx|{let turn=owner.take_input(cx.retained_grant());let work=turn.work;let(input,progress)=turn.result.unwrap().unwrap();output=Some(input);semio_framework_job::receive_original_retained_work(cx,RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(progress)),work})?;Ok(())}).unwrap();let output=output.unwrap();assert_eq!(output.layers[0].id,f["expected"]["layerId"].as_str().unwrap());assert_eq!(output.images[0].0,f["expected"]["imageKey"].as_str().unwrap());assert_eq!(serde_json::to_value(&output.images[0].1.pixels).unwrap(),f["expected"]["pixels"]);let mut retired=semio_framework_value::retirement::controlled::ControlledRetirement::retain(output);while !retired.terminal_is_empty(){caller.turn(loan(),|cx|{let demand=retired.selected_demand(32768)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|{let result=retired.step(grant);RetainedWorkOutcome{result,work:retired.last_turn_work()}})?;Ok(())}).unwrap();}}close(&mut caller,&mut owner);assert_eq!(document,before);semio_s_artifact_raster_raster_model::snapshot::retire_raster_snapshot(document);semio_s_artifact_raster_raster_model::snapshot::retire_raster_snapshot(before);caller.retire(stock());}}
